package vn.iotstar.controller;import jakarta.validation.Valid;import org.springframework.security.core.Authentication;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.validation.BindingResult;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import org.springframework.web.servlet.mvc.support.RedirectAttributes;import vn.iotstar.dto.ProductDTO;import vn.iotstar.security.CustomUserDetails;import vn.iotstar.service.ProductService;@Controller @RequestMapping("/products") public class ProductController{public ProductController(ProductService service){this.service=service;}final ProductService service;@GetMapping public String list(@RequestParam(defaultValue="")String keyword,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="10")int size,Model m){m.addAttribute("products",service.findAll(keyword,page,size));m.addAttribute("keyword",keyword);m.addAttribute("size",size);return "products/list";}@GetMapping("/create")public String create(Model m){m.addAttribute("productDTO",new ProductDTO());m.addAttribute("mode","create");return "products/form";}@PostMapping("/create")public String create(@Valid @ModelAttribute ProductDTO d,BindingResult r,@RequestParam(required=false)MultipartFile image,Authentication a,Model m,RedirectAttributes ra){if(r.hasErrors()){m.addAttribute("mode","create");return "products/form";}d.setUserId(((CustomUserDetails)a.getPrincipal()).getId());try{service.create(d,image);ra.addFlashAttribute("success","Tạo sản phẩm thành công.");return "redirect:/products";}catch(IllegalArgumentException e){r.reject("product.error",e.getMessage());m.addAttribute("mode","create");return "products/form";}}@GetMapping("/edit/{id}")public String edit(@PathVariable Long id,Model m){m.addAttribute("productDTO",service.findById(id));m.addAttribute("mode","edit");return "products/form";}@PostMapping("/edit/{id}")public String edit(@PathVariable Long id,@Valid @ModelAttribute ProductDTO d,BindingResult r,@RequestParam(required=false)MultipartFile image,Model m,RedirectAttributes a){if(r.hasErrors()){m.addAttribute("mode","edit");return "products/form";}try{service.update(id,d,image);a.addFlashAttribute("success","Cập nhật sản phẩm thành công.");}catch(IllegalArgumentException e){r.reject("product.error",e.getMessage());m.addAttribute("mode","edit");return "products/form";}return "redirect:/products";}@PostMapping("/delete/{id}")public String delete(@PathVariable Long id,RedirectAttributes a){try{service.delete(id);a.addFlashAttribute("success","Xóa sản phẩm thành công.");}catch(IllegalArgumentException e){a.addFlashAttribute("error",e.getMessage());}return "redirect:/products";}}
